WITH parsed AS (SELECT id, effective_from, tier_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, APPROX_PERCENTILE(avg_tier_price, 0.95) AS avg_tier_price_p95, PERCENTILE_APPROX(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, APPROX_PERCENTILE(avg_tier_price, 0.95) AS avg_tier_price_p95_2, AVG(avg_tier_price) AS avg_avg_tier_price FROM parsed GROUP BY ROLLUP (DATE_TRUNC('YEAR', effective_from)) HAVING AVG(avg_tier_price) < 1000000 ORDER BY year_start DESC NULLS LAST
